    intro: "Охотится на врагов со своей паучьей армией",
    lore: "Веками чёрная паучиха Арахния скрывалась в тёмных лавовых туннелях под тлеющими кратерами горы Пиротей, взращивая миллионы паучков и отправляя их охотиться на поверхности. Однажды визирь жадности Фолопталис воздвиг на склоне этого потухшего вулкана свой магнетитовый зиккурат, прекрасно зная: любым грабителям, что ищут его притягательные богатства, сначала придётся пройти через паучьи владения. \r\n\t\t\t\t<br><br>Тысячелетию материнского спокойствия пришёл конец: гору непрерывно осаждали мохноноги и воришки, смелые рыцари и благородные юноши — несомненно, очень питательные, но всё же мешающие воспитывать невинное паучье потомство. Устав от вторжений, Арахния нанесла Фолопталису визит, а когда тот отказался уступить, паучиха затянула его в шёлковый кокон и отложила до особого пира в честь дня рождения.\r\n\t\t\t\t<br><br>К несчастью, опустевший зиккурат лишь привлёк новых охотников за наживой. Когда один из паучков попал под ноги неуклюжего наглеца, материнскому терпению пришёл конец. Арахния направилась на поверхность и объявила: она избавит мир от каждого вредителя, вплоть до самого последнего героя — пока не убедится, что её драгоценные паучата растут в безопасности.",
