    lore: "Болтозвяк — выходец из того же смышлёного народца, что и Снайпер и Механик, и он также компенсирует свою низкорослость механическими приспособлениями и хитростью ума. Сын часовщика, Болтозвяк много лет учился ремеслу отца — до тех пор, пока война не сошла с гор и не унесла из равнинных поселений мирные профессии. «Теперь твоё ремесло — война», — сказал ему умирающий отец, пока деревня их прадедов дымилась, обугленная и сожжённая.\r\n\t\t\t\t<br><br>Плох тот ремесленник, который винит инструменты, и Болтозвяк был не из тех, что придумывал отговорки. Похоронив отца в руинах деревни, он устремился превратить себя в величайший инструмент войны всех миров и времён. Он поклялся, что его больше никогда не застанут врасплох — и соорудил, используя свои знания, механические доспехи, в сравнении с которыми снаряжение иноземцев было подобно консервным банкам. Теперь Болтозвяк живёт вместе со своими устройствами — некрупный, но смертоносный воин, разрушение и засада для которого стали способностями, работающими почти автоматически и точно, как часовой механизм. Механик смерти, он быстро кончает жизнь неподготовленных противников с помощью своих творений и несёт с собой новый век военной экипировки. Который час? Час Часовщика!",
