    lore: "Стремительный и хитрый стратег Иш'Кафэль — провидец, которому для уничтожения противника не требуется оружие. Он привык побеждать силой мысли, повергая врагов в замешательство и меняя ход битвы мановением своего тактического гения. Иш'Кафэль пришёл из измерения вне граней реальности, который он сам называет «миром за стеной».\r\n\t\t\t\t<br><br>Будучи великим военачальником и защитником святого короля Даматрикса, он без тени сомнения отправился на войну за Великий предел, но в последние её дни его войско пало. Неспособный справиться с превосходящими силами врага, провидец завёл преследователей в иллюзорный лабиринт, а затем совершил отчаянный поступок. В последний момент Иш'Кафэль прорвал окружение, выскользнул из лабиринта и выпустил сокрушительную волну тёмной энергии, навеки заточив в нём своих врагов. Опомнившись, верный провидец был рад осознать, что его народ в целости и сохранности, однако сам он оказался в неизвестном ему мире, неспособный вернуться домой. Теперь Иш'Кафэль поставил себе новую цель — доказать этому новому странному миру абсолютное величие своей стратегии.",
