    id: 33,
    key: "enigma",
    name: "Enigma",
    attribute: 3,
    intro: "Затягивает врагов в чёрную дыру, нанося им урон",
    lore: "О происхождении этой сущности неизвестно ровным счётом ничего. С древних времён остались лишь истории и легенды, и большинство из них даже не похожи на правду. По сути, это существо — великая загадка, и известно об нём лишь одно: оно — вселенская сила, поглотитель миров. Оно — дитя пустоты, иногда материальное, иногда — бесплотное. Чудище, живущее вне измерений.\r\n\t\t\t\t<br><br>Одни говорят, что раньше оно было великим алхимиком, пытавшимся раскрыть секреты вселенной, но проклятым за свою заносчивость. Другие называют его непостижимым древним существом, самой бездной, неясным голосом первозданной тьмы, в которой зиждился первый свет. А самые старые легенды гласят, что это первая взорвавшаяся звезда, разумная чёрная дыра — безжалостное существо c туманными намерениями и разрушительной силой, низвергнувшееся на этот мир.",
