    id: 59,
    key: "huskar",
    name: "Huskar",
    attribute: 0,
    intro: "Жертвует своим здоровьем, чтобы наносить больше урона",
    lore: "Очнувшись от агонии священного мира Нотл, воин открыл глаза и узрел, как одарённый жрец теней накладывает на него глубокое заклятие. Вопреки древним обрядам ордена Дезун душа воина была спасена от вечности, но, как и все побывавшие в мире Нотл, он необратимо изменился. Более неподвластная смертной плоти, его кровь обратилась источником невообразимой силы; каждая пролитая капля с лихвой возвращалась лютой, горящей мощью. Однако новообретённый дар разъярил спасённого, ведь жрец теней лишил его места среди богов, отказал в собственном священном жертвоприношении.\r\n\t\t\t\t<br><br>Со временем старейшины ордена собрались расширить своё влияние и согласились между собой, что такой внушительный боец пригодится в грядущих кампаниях. Однако воин не желал быть жалким оружием ордена, что отказал ему в родовых правах. Когда на горизонте воспылали первые огни восходящей войны, он покинул отчий дом, чтобы найти новых союзников и достойный повод выпустить силу, что придёт с его безраздельным самопожертвованием.",
