    id: 64,
    key: "jakiro",
    name: "Jakiro",
    attribute: 2,
    intro: "Замораживает и обжигает врагов своими заклинаниями",
    lore: "Даже среди магических существ двуглавый дракон считается уродом. Поровну вмещающий в себя лед и пламя, коварство и ярость, он парит над обугленными и замороженными полями битв и изничтожает любого, кто осмелится бросить ему вызов. Яйца пироксианских драконов вмещают двух детенышей. Знаменитые своим злобным нравом с первых мгновений жизни, едва вылупившиеся детёныши пытаются убить друг друга ещё в гнезде. Выживает сильнейший. Так из поколения в поколение сохраняется сила пироксианского вида. Но по ошибке природы из одного яйца вылупился двуглавый уродец, объединив в одном теле все сильные стороны пироксианского древа. Запрятанные под мощной чешуёй силы льда и огня объединяются, и от них не спастись никому.",
