    lore: "«С самого рождения за мою голову назначена награда. Она росла вместе с моим навыком устраивать переполох. Каждый раз, когда королева Империя её повышала, я понимал, что делаю всё правильно. Пожалуй, самый большой минус долгого нахождения в Айсреке — это то, что теперь мне придётся изрядно потрудиться, чтобы вернуть цену за свою голову на достойный уровень».",
