    lore: "При жизни Этриан (тогда ещё не Лич) был могущественным колдуном — его легендарные заклинания обращали в лёд города и могли погрести под снежными бурями целые королевства. А у кого есть сила, у того есть и завистники. Несколько магов тщательно проработали покушение на Этриана и, ко всеобщему удивлению, дилетанты достигли успеха, поймав колдуна врасплох, обезоружив его и заковав в волшебные цепи. Этриана доставили к бездонному озеру и торжественно сбросили в тёмные воды. Но озеро было не таким уж и бездонным.\r\n\t\t\t\t<br><br>Этриан опускался глубже и глубже в течение года, пока, наконец, не зацепился за скалистый выступ в стене бездонного колодца. Там он и остался висеть, мёртвый, но не разлагающийся. Спустя многие годы некромант Анхил решил проверить, действительно ли бездонно это озеро, и отправился в экспедицию. Отвес, который Анхил опускал в воду, нашёл связанного Этриана. Анхил, обрадовавшись неведомой добыче, поспешил извлечь труп из воды. К сожалению, слишком много времени прошло с момента погребения Этриана и не нашлось никого, кто предупредил бы Анхила об опасности. Наивный волшебник расковал Этриана и провёл ритуал воскрешения. Некромант понял, что просчитался, только в тот момент, когда Lich открыл глаза и щелчком пальца разорвал волшебника на куски.",
