    lore: "В темнице Деварка томился закованный в кандалы мстительный маг, замышлявший побег. Он делил камеру с невнятно бормочущим существом по имени Н'эйкс — вором, которого Чёрствый совет проклял вечной жизнью, чтобы наказание за воровство и мошенничество проучило его как следует. За долгие годы цепи заключённого проржавели, как и его разум, и Н'эйкс уже не помнил, кем был раньше, и больше не мечтал сбежать.\r\n\t\t\t\t<br><br>В нём волшебник увидел идеальный инструмент и, сплетя заклинание Заражения, заключил свою жизненную силу в тело вора, чтобы заставить того пожертвовать собой и пройти по подземельям ураганом разрушения, пока сам маг вернулся бы в своё тело и сбежал незамеченным. Но разум мага оказался в таком мощном водовороте безумия, что всего его планы были забыты, а воля сломлена. А вот Н'эйкс, которого внезапный прилив свежей жизни пробудил от кошмарного безумия, подчинился бесплотному голосу у себя в черепной коробке, который повторял лишь одно слово: «Сбежать».\r\n\t\t\t\t<br><br>В тот момент и родилось это существо. Оно поглощало сознание стражей и солдат, заставляя тех открывать замки и убивать друг друга, и вышло на свободу, питаясь жизнью жертв. Оно до сих пор носит на себе разорванные кандалы, чтобы каждый знал: никто больше не заберёт его свободу... Но до сих пор он остаётся узником. В одном теле живут две сущности: безымянный жестокий вор и Хозяин, чьему гласу вор будто бы подчиняется.",
