    id: 80,
    key: "lone_druid",
    name: "Lone Druid",
    attribute: 1,
    intro: "Командует могучим духом-медведем",
    lore: "Ещё до того, как пошли первые истории и были написаны первые книги, уже был Клан Медведя. Мудры и справедливы были его члены, и главной их целью было понимание порядков природы. Высшие силы природы узрели их, и потребовали мудрейших к себе. Старый жрец Силла, судья и провидец клана, выступил из рядов своих соплеменников: «Когда затухнет последний свет этого мира, когда цивилизация покинет эти земли, когда мир будет повержен и испещрён бесконечными пустынями конца миров, посади Семя».\r\n\t\t\t\t<br><br>Наполнившись верой, Силла почувствовал, как вес лет на его плечах стал легче, а молодецкая юркость понемногу возвращалась в тело. В разум его впитывалось непомерное знание. Он стал способен материализовывать свою волю в материи, и, с небольшим усилием концентрации, менять собственную физическую форму. Но все же злые языки и податливые уши разнесли слово о Семени до других людей, и те обрушились войной на Клан Медведя.\r\n\t\t\t\t<br><br>Прошли годы, и легенды, и даже само время позабыли про Клан Медведя, позабыли про Силлу и Семя, позабыли множественные величественные цивилизации, воспрявшие и павшие там, где когда-то был Клан. Веками и тысячелетиями Силла ждал: ждал весточки от своих божеств, ждал конца войны в вечно буйствующих землях, ждал в отшельничестве и в тайне ото всех, ждал конца всех вещей и завершения его священной миссии, всегда готовый уничтожить то, что помешало бы свершению посева.",
    image:
      "https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/lone_druid.png",
