    attribute: 1,
    intro: "Бросает во врагов отскакивающие снаряды",
    lore: "Как она опустилась до такого? Бич равнин, беспощадный повелитель людей и зверей, она могла сеять страх там, где ей вздумается. Теперь она была далеко от своей родины, на грани безумия от голода и месяцев скитаний, а её армия либо была давно мертва, либо их настигла участь хуже смерти. Едва она преступила границу древнего леса, в темноте блеснул пылающий взор. Что-то красивое и смертельное искало себе добычу в увядающих сумерках. Бесшумно оно развернулось и ушло. Ей завладела ярость. Схватив ржавый кинжал, она ринулась вслед за зверем, в надежде вернуть хотя бы частичку былой славы, но добыча все ускользала от неё. Три раза она загоняла зверя в угол, и три раза она нападала, но видела лишь ускользающую в леса тень. Освещая все вокруг, взошла полная луна, и отследить зверя стало легче.\r\n\t\t\t\t<br><br>Достигнув светлой вершины холма, огромная кошка, более не скрываясь, сидела в ожидании. Когда женщина стала размахивать кинжалом, зверь поднялся, взревел и кинулся на неё. Казалось, смерть наконец настигла её. Но она спокойно остановилась. Через мгновение зверь выбил кинжал из её рук и исчез в лесу. Тишина. Фигуры в капюшонах приблизились к ней. В почтительных тонах они поведали, что Селемине, Богиня Луны выбрала её, вела её и испытала её. Невольно она выполнила священный ритуал Темной Луны, воинов Серебряных лесов.\r\n\t\t\t\t<br><br>Ей предложили выбор: присоединиться к Темной Луне и поклясться служить Селемине или уйти и никогда не возвращаться. Она не колебалась. Принимая своё освобождение, она отказалась от кровавого прошлого, и с тех пор её имя — Luna, устрашающая лунная наездница, беспощадная и непоколебимая защитница Серебряных лесов.",
