    id: 77,
    key: "lycan",
    name: "Lycan",
    attribute: 0,
    intro: "Превращается в свирепого волка",
    lore: "Бэйнхаллоу с рождения принадлежал благородному дому Эмбри, могущественнейшему из всех землевладельческих родов королевства Слом. Ещё до того, как свершилось Падение, дом Эмбри первым восстал против ненасытного короля, чьи желания становились всё страннее и страннее, а двор его заполонили колдуны и шарлатаны. Не желая больше платить вассальские залоги, Эмбри послали в столицу шеститысячную армию, но её перерезали в сражении, названным позже «Бойней отступников». Тогда старое выражение показало свою настоящую шкуру: когда метишь в шею королю, лучше рубить сразу всю голову.\r\n\t\t\t\t<br><br>Разъярённый свершившимся предательством, король истребил всякого живущего Эмбри, оставив жизнь лишь лорду и его младшему сыну, Бэйнхаллоу. Опозоренный лорд был прикован к узорчатому мраморному полу королевской залы, и монарх приказал своим волшебникам превратить мальчика в волка, чтобы тот разодрал глотку своему же отцу. «Сделайте это, — сказал король, — чтобы Лорд Эмбри осознал, как остры зубы предательства». Были призваны сильнейшие магические силы, и тело ребёнка исказилось. Однако в то время как тело Бэйнхаллоу больше не было человеческим, его душа осталась на месте — и вместо того, чтобы разодрать шею беззащитного отца, он набросился на прислугу монарха. Прежде чем волка наконец-то смогли выгнать из замка, далеко в ночь, он разорвал на клочки дюжину королевских рыцарей. Лорд Эмбри, всё ещё в кандалах, смеялся, даже когда его тело пронзил королевский меч. Теперь же Бэйнхаллоу — наследник потерянного дома Эмбри, бродящий по миру под именем Lycan. Наполовину воин, наполовину волк, он ищет возмездия за всё то, что потерял.",
