    lore: "У Марси много обожателей, но о её происхождении известно немногим. Обычно она сопровождает в пути принцессу Мирану, но корни их дружбы сплетены в таких секретах, которые ни одна из них не раскроет без надобности. Для союзников она — беспощадная и честная защитница. Для противников же — бесстрашное препятствие на пути к тем, кого она считает друзьями. Неразумные оппоненты могут счесть её телосложение невыдающимся, но внутренняя сила наделяет удары Марси невероятной мощью. Она истребит всех, кто решит встать у неё на пути, но до последнего вздоха будет хладнокровной сторонницей того, кто заслужит её доверие.",
