    attribute: 1,
    intro: "Останавливает врагов каменным взором",
    lore: "«Красота — страшная сила». Этой мыслью утешала себя самая юная и прелестная горгона с раннего детства, ибо ей единственной из трёх прекрасных дочерей морской богини не довелось родиться бессмертной. Всё изменилось в тот роковой день, когда неизвестные в масках ворвались в обитель горгон и похитили её сестер, бесстрастные к их красоте и слезам. Схвативший Медузу тут же отбросил её с отвращением: «От неё разит, как от смертной! Такие нам ни к чему». Медуза, сгорая от унижения и ярости, поспешила в храм матери, пала пред богиней и взмолилась: «Раз не удостоена я бессмертия, прошу, дай мне силу — дабы я вызволила своих сестёр и посвятила остаток жизни мщению за эту несправедливость». Долго размышляла богиня, и, наконец, даровала Медузе прошенное. Взамен на свою воспеваемую красоту Медуза получила устрашающий лик и ещё более ужасающую мощь. Ни на мгновение не пожалела она о своем выборе, ведь знала: единственная красота, которой стоит обладать, — это сила, ибо лишь сила изменит мир.",
    image:
      "https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/medusa.png",
    logo: "https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/icons/medusa.png",
