    id: 9,
    key: "mirana",
    name: "Mirana",
    attribute: 1,
    intro: "Оглушает врагов точными попаданиями стрел",
    lore: "Наследница королевской династии и первая претендентка на Лучезарный трон отреклась от мирских земель и титулов, посвятив свою жизнь богине Луны Селемине. С тех пор зовётся она принцессой Луны. Ревностно охраняет она неприкосновенные Серебристые Леса от любого, кто осмелится сорвать хоть цветок священного лучистого лотоса, растущего в заповедных серебряных запрудах. Разъезжая на огромном звере из рода благородных кошек, с гордостью и отвагой несёт она службу в гармонии с лунными фазами и движением великих созвездий. Укреплённый накладкой из лунной породы лук наделяет её стрелы могуществом ночного светила.",
