    name: "Necrophos",
    attribute: 2,
    intro: "Одновременно лечит союзников и наносит урон врагам",
    lore: "В годы ужасной чумы один безвестный монах с дурными наклонностями по имени Ротунд'йер неожиданно для себя занял пост кардинала: все другие претенденты на должность скоропостижно скончались. В то время как другие братья-монахи облегчали участь больных, новоиспечённый кардинал заседал в Соборе Румуска, обещая умирающим богачам духовное вознаграждение, коли те передадут свои земли их ордену. Со временем чума угасла, оставив лишь пару неуступчивых очагов, а на деяния Ротунд'йера обратила внимание высшая власть. Бывшего кардинала обвинили в ереси и отрядили ухаживать за чумными, где его медленно и мучительно пожрала бы болезнь. Но судьи не учли, что чума стала Ротунд'йеру родной. Хворь вошла в тело монаха — но не убила, а стала кормить его силы и превратила в сущего чумного мага, Епископа мора. Теперь он ходит по земле, распространяя свою эпидемию, и мощь его растёт с каждой деревней, сгинувшей в его губительном присутствии.",
