    attribute: 0,
    intro: "Усиливает свои заклинания щепоткой удачи",
    lore: "Огр обыкновенный — создание, для описания мыслительных способностей которого отлично подходит фраза «туп как пень». В повседневной жизни огр решительно неспособен на какой-либо осмысленный поступок. Обычно он одевается в грязь, но иногда может обнаружить себя случайно завернувшимся в звериные шкуры, только что этими самыми зверями пообедав. Не назовёшь огра и социальным существом: чаще всего его можно повстречать в компании нежно обожаемого камня или пня, принятого за кого-то из своих (этим можно объяснить низкий уровень рождаемости у огров). Однако примерно раз в поколение на незадачливую расу снисходит благословение — рождение двухголового Ogre Magi, которому сразу же даётся традиционное имя Аггрон Камнелом — так звали первого и, возможно, единственного мудрого огра за всю их родословную.\r\n\t\t\t\t<br><br>С двумя головами Ogre Magi уже способен функционировать на уровне, которого большинство других видов достигают с одной. Хоть он и не сможет никого переспорить (даже самого себя), ему ниспослана так называемая «удача дурака» — склонность к необъяснимым чередам невероятного везения, которые позволяют расе огров блистать, невзирая на врагов, жестокие погодные условия и неспособность прокормить себя. Будто бы сама богиня удачи, переполненная жалостью к печально недалёким существам, взяла Ogre Magi к себе под крыло. И кто станет её винить? Бедняжки.",
