    name: "Pugna",
    attribute: 2,
    intro: "Высасывает из врага жизнь, чтобы излечиться самому",
    lore: "В родном мире Pugna, неподалёку от пробоин в Пределах пустоты, стоял ламаистский монастырь магии забвения, питавшийся энергией, идущей из проходов в Пределы. Настоятель храма отошёл в Забвение несколько лет назад, оставив академию без предводителя. Сразу же после смерти своего учителя, регенты монастыря приступили к ритуалам поиска нового воплощения своего учителя, и, в конце концов, все знаки указали на ближайшие поселения. Несколько деревень притулились в тени храма, и их улицы и площади были заполнены смехом и криками детей.\r\n\t\t\t\t<br><br>Pugna, младенец тринадцати месяцев от роду, был лишь одним из множества кандидатов среди местных непосед, и в назначенный день его представили ламам вместе с ещё двумя маленькими кандидатами. Детям была подана горсть поношенных реликвий, некогда принадлежавших настоятелю. Один мальчик схватил порфировую палочку, принадлежавшую ламе,... и стал ковыряться ей у себя в ноздре. Неусидчивая девчонка заграбастала амулет ламы, после чего сразу его проглотила. Pugna невозмутимо посмотрел на обоих, весело рассмеялся и испепелил их зарядами изумрудного пламени. Потом вытащил палочку и амулет из двух кучек праха, и крикнул: «Моё!». Регенты монастыря подхватили малыша на плечи, обмотали его в одеяния старого хозяина, и спешно понесли ребёнка к его трону, пока у их старого нового учителя не сменилось настроение. В течение пяти лет правления Pugna, к его нескончаемому удовольствию, кучей пепла стала уже вся академия.",
