    lore: "Приветствую, приветствую всех, кто пришёл увидеть, как под светом софитов разыграется феерия на все времена! Готовьтесь, ведь ваши рассудки будут разбиты! Ваши ожидания — разрушены! А ваши Древние — разгромлены в пух и прах!<br><br>Узрите невообразимые трюки и авантюры единственного и неповторимого чуда механики, великого Колиостро Кеттла! Магистр манежа, знаток пыток и гений своего времени явился с одной целью: развлечь и измучить любого героя, осмелившегося отдёрнуть пурпурную портьеру карнавала и взглянуть на таящиеся за ней секреты.<br><br>Большинство маэстро ждут, пока публика придёт к ним — большая ошибка! Магистр манежа знает, что аудиторию нужно <i>найти</i>. <i>Затащить</i> к себе. И <i>заставить</i> смотреть.",
