    lore: "Слардар из рода змееногих, один из обитателей глубин, охраняет обширную сеть затонувших городов и скрытых ими древних ценностей. Он стоит на страже потайных сокровищниц, скрытых в бессветной пучине, и неусыпно охраняет их от подводных воров, посланных на морское дно алчными магами с поверхности. Страж верен своей службе как никто, а за его молчаливостью скрыто знание всех тайных морских проходов. Несмотря на жгучий свет, он поднимается на мелководье, чтобы разведать, не сговаривается ли кто против моря, — а иногда и чтобы расправиться с теми немногими, кто всё же обворовал затонувшую сокровищницу. Проведённое под огромным давлением морской толщи время сделало из змееногого стража существо невероятной мощи.",
