    lore: "Путешествуя по пустынным дорогам и оазисам Нанарака, засушливого преддверия в Чужеземье, истощённые и отчаянно цепляющиеся за жизнь люди всегда рады увидеть Беатрикс Пороховницу и её драконью жабу Мортимера.<br><br>Пережив многих собратьев по ремеслу благодаря острому уму и верной руке, Беатриша прославилась не только как непревзойдённая оружейница, но и как мудрая и жизнерадостная дама почтенного возраста, пекущая самое лакомое на свете пороховое печенье.<br><br>Потому-то Чужеземье и усыпано костьми бандитов и негодников, вздумавших провести добродушную старушку.",
