    lore: "Внебрачный сын вигильского рыцаря и девы из рода бледных мерансов рос в руинах Тенистого взморья. Его отца казнили за нарушение Вигильского кодекса, а от матери отвернулись все родичи, и поэтому бастард считает, что честь следует искать не в обществе, но в себе. Он заботился о матери до самой её нескорой смерти, а затем отправился на службу вигильским рыцарям, не раскрывая своего происхождения. Тринадцать лет он учился в школе своего отца, постигая суровый закон, что презирал само его существование. И вот, в день присяги, он завладел Клинком изгоя, разбил Священный шлем и сжёг кодекс в праведном вигильском пламени. Он покинул цитадель, навсегда одинокий, строго следующий своим личным законам до последней руны. Да, он рыцарь... но рыцарь мятежный. Рыцарь, верный только себе.",
