    intro: "Замедляет врагов своими ловушками",
    lore: "Ланайя, Templar Assassin, стала той, кто она есть, благодаря своему врождённому любопытству. Эта обладательница проницательного ума потратила юные годы на тщательное изучение законов природы. Она зачитывалась гримуарами по магии и алхимии, проводила эксперименты, описанные на обугленных страницах Фиолетовых архивов, запоминала наблюдения учёных из смышлёного народца. Тихая и скрытная от природы, она всё больше развивала эти свои навыки, ведь новые знания находились всё труднее. Будь она чуть скромнее, гильдии знала бы её как вора-учёного. Но исследования заводили её во всё более дальние и тёмные места.\r\n\t\t\t\t<br><br>Посвятив себя изучению законов природы, она смогла открыть секретную дверь самого мироздания: вход в самый тайный из храмов. Сущности по ту сторону портала, казалось, ждали её. Тайны, открытые ими Ланайе, были просто ничем по сравнению с ответами, которые они согласились дать ей в обмен на служение. Ланайя поклялась охранять секреты, но, что важнее, она получила возможность утолить свою нестерпимую жажду знаний. И тухнущие взгляды повергаемых её врагов тоже понемногу открывают ей тайны мироздания.",
