    id: 29,
    key: "tidehunter",
    name: "Tidehunter",
    attribute: 0,
    intro: "Стойко переносит получаемый урон",
    lore: "Когда-то Левиафан был защитником Затонувших островов, но намерения его народа крайне расплывчаты. Все мы знаем о том, как для жителей суши важны морские торговые пути и как борьба за открытые воды воздвигает и низвергает целые империи. Куда меньше нам известно о подводных маршрутах, о враждующих племенах мерансской общины, образовавших поселения в бесчисленных подводных стычках. В хрупком перемирии меж сушей и мерансами мы едва ли можем оценить размах морских империй, и политика их сложна и смутна. Вполне возможно, что Левиафан устал от мелочных распрей и стал жить отдельно, преданный лишь своему глубоководному богу Мэльрону Щупальцеликому. Теперь он рыскает по мелководью в поисках людей и мерансов, смеющих перейти ему дорогу, — и в особенности не жалует одного кладдского адмирала, вражда с которым древна и загадочна, как самые глубокие морские впадины.",
