    name: "Undying",
    attribute: 0,
    intro: "Призывает полчища зомби, атакующих врага",
    lore: "Как давно он потерял своё имя? Запустелые руины его разума больше не знают.\r\n\t\t\t\t<br><br>Он смутно припоминает доспехи, знамёна и угрюмых собратьев, скачущих бок о бок. Он помнит битву: боль и страх мёртвой хваткой вырвали его из седла. Он помнит ужас, когда вместе с другими воинами пал в бездонный зев Мёртвого бога в угоду его голоду и погребальной песни. В глубокой тьме их покинуло время. Их покинули мысли. Их покинул разум. Но не голод. Брат поднял на брата ломаные зубы и ногти. И началось: сначала далёкая, едва слышимая нота, за ней другая, затем ещё одна, неизбежно и нескончаемо. Этот хор постепенно вырос в сплошную стену звука, пожирающую все прочие мысли, пока не осталось оных. Песнь панихиды поглотила воина, и он простёр свои руки к Мёртвому богу, принявший свою участь. Но ей была отнюдь не смерть. Мёртвый бог требовал войны. В чреве великой бездны он узнал своё новое предназначение: нести погребальную песнь, поднимая мертвецов против ещё живых существ. Его новое имя — Undying, глашатай Мёртвого бога. Его новая цель — восстать, пасть и восстать вновь, лишь бы песнь смерти не прекращала литься ни на миг.",
