    lore: "В тихом свете Нижних пределов, отрезанных от внешнего мира тектоническим сдвигом, многие миллионы лет обитала раса низших драконов. Один из них, особенно злобный и любопытный, был только рад покинуть опостылевшие пещеры, попавшись в руки наивному магу-изуверу. Змий притворялся верным питомцем колдуна, надеясь постичь его тёмную магию — но вскоре понял, что родная отрава жалит куда злее многих заклинаний. Драконья кислота легко справилась с прутьями клетки. Вырвавшись из заточения, ядовитым плевком ослепил он старого заклинателя и упорхнул на волю, дабы явить миру нового владыку.",
