    id: 37,
    key: "warlock",
    name: "Warlock",
    attribute: 2,
    intro: "Призывает на свою сторону могучих демонов",
    lore: "Будучи старшим хранителем и главой отдела приобретений в скрытых архивах Ультимирской академии, Демнок Лэнник неустанно искал затерянные, редкие и запретные тома. Ни проклятые храмы, ни коварные пещерные ходы — ничто не заставило бы Демнока свернуть с тропы, стоило ему прознать, что, быть может, в конце пути он найдет хотя бы жалкий кусочек свитка с древними знаниями. И так часто приходилось ему сталкиваться с сущностями, оставленными защищать эти древние знания, что он наконец посчитал необходимым изучить таинства магии. С такой же одержимостью принялся Демнок за учение, с какой отправлялся в опаснейшие походы за записями — и превзошёл всех чернокнижников Ультимирской академии за время, которого остальным хватило бы, лишь чтобы изучить самые основы. В последнюю очередь он вырезал себе посох из дредвудского дерева и заточил в него духа из Глубин Ада. И, ожидая дня, когда он найдёт последнюю затерянную книгу заклинаний, Демнок приступил к своему собственному произведению — «Чёрному гримуару». Сомнений нет: он будет весьма поучительным.",
