    lore: "В течение долгих лет король Остарион создавал империю из останков своих врагов. Вечная деспотическая власть стала его навязчивой идеей, полностью охватившей рассудок. Он считал, что башни, построенные рядом с его дворцом, смогут сохранить его жизнь навсегда. Позднее он осознал, что это было глубокое заблуждение... Ведь даже кости однажды обратятся в прах. Глубоко разочарованный недолговечностью плоти, он начал искать более надежный способ, чтобы продлить свое правление и, в конце концов, нашел его. Это была спектральная энергия, форма чистого духа, которую некоторые чудовища выделяют в момент смерти. Вселив в себя их призрачное естество, он надеялся обрести столь же мощное и бессмертное тело, каким было его эго. Во время тысячелетнего солнцестояния, также известного как ночь призраков, он подготовил обряд превращения и приказал своим подданным собрать достаточное количество душ, которое поможет приблизить его к бессмертию. Никто не знает, сколько отчаянных героев пало в ту ночь. Единственным уцелевшим в этой бойне оказался сам король, переродившийся во Wraith King на следующее утро с восходом солнца. Отныне он не восседает на своем престоле, а идет на поле боя с мечом в руке и требует верности, не только до самой смерти, но и за ее пределами.",
